function openCompanyView(){
  if(!isOwner())return;
  const c = state.companyInfo || {};
  document.getElementById('co-full-name').value = c.full_name || '';
  document.getElementById('co-short-name').value = c.short_name || '';
  document.getElementById('co-director').value = c.director || '';
  document.getElementById('co-inn').value = c.inn || '';
  document.getElementById('co-kpp').value = c.kpp || '';
  document.getElementById('co-ogrn').value = c.ogrn || '';
  document.getElementById('co-tax-system').value = c.tax_system || '';
  document.getElementById('co-legal-addr').value = c.legal_address || '';
  document.getElementById('co-phone').value = c.phone || '';
  document.getElementById('co-email').value = c.email || '';
  document.getElementById('co-bank-name').value = c.bank_name || '';
  document.getElementById('co-bank-account').value = c.bank_account || '';
  document.getElementById('co-bik').value = c.bik || '';
  document.getElementById('co-corr-account').value = c.corr_account || '';
  document.getElementById('co-card-number').value = c.card_number || '';
  document.getElementById('co-card-holder').value = c.card_holder || '';
  document.getElementById('co-card-bank').value = c.card_bank || '';

  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  document.getElementById('view-company').classList.add('active');
  window.scrollTo(0,0);
}

// Настройка «Ставка за м²» для каталога готовых проектов — видна только
// редакторам каталога (canEditCards), как и сама вкладка «Каталог».
function renderCatalogPriceSettings(){
  const section = document.getElementById('catalogPriceSection');
  const card = document.getElementById('catalogPriceCard');
  if(!section || !card) return;
  if(!canEditCards()){ section.style.display = 'none'; card.style.display = 'none'; return; }
  section.style.display = '';
  card.style.display = '';
  const input = document.getElementById('catalog-price-per-sqm');
  if(input) input.value = getCatalogPricePerSqm();
}

async function saveCatalogPricePerSqm(){
  if(!session?.isAdmin){showToast("Требуются права администратора");return;}
  const val = parseFloat(document.getElementById('catalog-price-per-sqm').value);
  if(!val || val <= 0){ showToast('Укажите положительную ставку'); return; }
  showToast('Сохранение…');
  try{
    if(state.companyInfo && state.companyInfo.id){
      const {error} = await sb.from('company_info').update({price_per_sqm: val}).eq('id', state.companyInfo.id);
      if(error) throw error;
    }
    state.companyInfo = {...(state.companyInfo||{}), price_per_sqm: val};
    showToast('Ставка сохранена');
  }catch(e){ console.error(e); showToast('Ошибка сохранения'); }
}

async function saveCompanyInfo(){
  if(!session?.isAdmin){showToast("Требуются права администратора");return;}
  const payload = {
    full_name: document.getElementById('co-full-name').value.trim(),
    short_name: document.getElementById('co-short-name').value.trim(),
    director: document.getElementById('co-director').value.trim(),
    inn: document.getElementById('co-inn').value.trim(),
    kpp: document.getElementById('co-kpp').value.trim(),
    ogrn: document.getElementById('co-ogrn').value.trim(),
    tax_system: document.getElementById('co-tax-system').value.trim(),
    legal_address: document.getElementById('co-legal-addr').value.trim(),
    phone: document.getElementById('co-phone').value.trim(),
    email: document.getElementById('co-email').value.trim(),
    bank_name: document.getElementById('co-bank-name').value.trim(),
    bank_account: document.getElementById('co-bank-account').value.trim(),
    bik: document.getElementById('co-bik').value.trim(),
    corr_account: document.getElementById('co-corr-account').value.trim(),
    card_number: document.getElementById('co-card-number').value.trim(),
    card_holder: document.getElementById('co-card-holder').value.trim(),
    card_bank: document.getElementById('co-card-bank').value.trim(),
    updated_at: new Date().toISOString(),
  };

  showToast('Сохранение…');
  try{
    if(state.companyInfo && state.companyInfo.id){
      const {error} = await sb.from('company_info').update(payload).eq('id', state.companyInfo.id);
      if(error) throw error;
    }else{
      const {error} = await sb.from('company_info').insert(payload);
      if(error) throw error;
    }
    showToast('Реквизиты сохранены');
    await loadAll();
  }catch(e){
    console.error(e);
    showToast('Ошибка сохранения');
  }
}

function getCompanyExportSections(scope){
    const general = {
      'Полное наименование': document.getElementById('co-full-name').value,
      'Краткое наименование': document.getElementById('co-short-name').value,
      'Генеральный директор': document.getElementById('co-director').value,
      'ИНН': document.getElementById('co-inn').value,
      'КПП': document.getElementById('co-kpp').value,
      'ОГРН': document.getElementById('co-ogrn').value,
      'Система налогообложения': document.getElementById('co-tax-system').value,
      'Юридический адрес': document.getElementById('co-legal-addr').value,
      'Телефон': document.getElementById('co-phone').value,
      'Email': document.getElementById('co-email').value,
  };
    const account = {
      'Банк': document.getElementById('co-bank-name').value,
      'Номер счёта (р/с)': document.getElementById('co-bank-account').value,
      'БИК банка': document.getElementById('co-bik').value,
      'Корр. счёт': document.getElementById('co-corr-account').value,
  };
    const card = {
      'Номер карты': document.getElementById('co-card-number').value,
      'Получатель (ФИО)': document.getElementById('co-card-holder').value,
      'Банк карты': document.getElementById('co-card-bank').value,
  };
    const sections = [];
    if(scope==='all'||scope==='general') sections.push({title:'Общие данные', data: general});
    if(scope==='all'||scope==='account') sections.push({title:'Оплата на расчётный счёт', data: account});
    if(scope==='all'||scope==='card') sections.push({title:'Оплата на банковскую карту', data: card});
    return sections;
  }

  function exportCompanyInfo(){
    const scope = document.getElementById('co-export-scope').value;
    const format = document.getElementById('co-export-format').value;
    const sections = getCompanyExportSections(scope);
    const companyName = (document.getElementById('co-short-name').value || document.getElementById('co-full-name').value || 'Company').trim();
    const safeName = companyName.replace(/[^a-zA-Zа-яА-Я0-9]/g,'_').slice(0,40) || 'Company';
    const fileBase = 'Rekvizity-' + safeName + '-' + financeToday();

    if(format==='pdf'){
      const { jsPDF } = window.jspdf;
      const doc = new jsPDF({unit:'mm', format:'a4'});
      registerPdfFonts(doc);
      const margin = 15; let y = 20;
      const pageWidth = doc.internal.pageSize.getWidth();
      doc.setFont('Roboto','bold'); doc.setFontSize(16); doc.setTextColor(0);
      doc.text('Реквизиты компании', margin, y); y += 10;
      sections.forEach(sec=>{
        if(y>270){ doc.addPage(); y=20; }
        doc.setFont('Roboto','bold'); doc.setFontSize(11); doc.setTextColor(0);
        doc.text(sec.title, margin, y); y += 6;
        doc.setFont('Roboto','normal'); doc.setFontSize(10); doc.setTextColor(60);
        Object.entries(sec.data).forEach(([label,val])=>{
          if(!val) return;
          if(y>280){ doc.addPage(); y=20; }
          const lines = doc.splitTextToSize(label+': '+val, pageWidth - margin*2);
          lines.forEach(line=>{ doc.text(line, margin, y); y+=5.5; });
  });
        y += 4;
  });
      doc.save(fileBase + '.pdf');
      showToast('PDF скачивается...');
  } else if(format==='excel'){
      const wsData = [];
      sections.forEach(sec=>{
        wsData.push([sec.title]);
        Object.entries(sec.data).forEach(([label,val])=>{ wsData.push([label, val || '']); });
        wsData.push([]);
  });
      const ws = XLSX.utils.aoa_to_sheet(wsData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'Реквизиты');
      XLSX.writeFile(wb, fileBase + '.xlsx');
      showToast('Excel скачивается...');
  } else {
      let html = '<html><head><meta charset=\'utf-8\'><title>Реквизиты</title></head><body>';
      html += '<h2>Реквизиты компании</h2>';
      sections.forEach(sec=>{
        html += '<h3>'+escapeHtml(sec.title)+'</h3><table border=\'0\' cellpadding=\'4\'>';
        Object.entries(sec.data).forEach(([label,val])=>{
          if(!val) return;
          html += '<tr><td><b>'+escapeHtml(label)+'</b></td><td>'+escapeHtml(val)+'</td></tr>';
  });
        html += '</table>';
  });
      html += '</body></html>';
      const blob = new Blob(['\ufeff', html], {type:'application/msword'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = fileBase + '.doc';
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setTimeout(()=>URL.revokeObjectURL(url), 1000);
      showToast('Word скачивается...');
  }
  }
// KP payment method (account / card) — selected in-session
let kpPaymentMethod = 'account';

function kpFileName(data, ext){
  const parts = ['КП', data.clientName || 'Клиент'];
  if(data.object) parts.push(data.object);
  const safe = parts.map(p=>p.replace(/[^a-zA-Zа-яА-Я0-9 ]/g,'').trim().replace(/\s+/g,'_')).filter(Boolean);
  return safe.join('-') + '.' + ext;
}

function getKpData(){
  const flat = kpFlatCatalog();
  const totals = updateKpTotals();
  const c = state.companyInfo || {};
  return {
    clientName: document.getElementById('kp-client-name').value.trim() || 'Клиент',
    clientPhone: document.getElementById('kp-client-phone').value.trim(),
    date: document.getElementById('kp-date').value || financeToday(),
    object: document.getElementById('kp-object').value.trim(),
    deadline: document.getElementById('kp-deadline').value.trim(),
    startDate: document.getElementById('kp-start').value.trim(),
    showCompany: document.getElementById('kp-show-company')?.checked !== false,
    showAccount: document.getElementById('kp-show-account')?.checked === true,
    showCard: document.getElementById('kp-show-card')?.checked === true,
    company: c.short_name || c.full_name || '',
    inn: c.inn || '',
    kpp: c.kpp || '',
    ogrn: c.ogrn || '',
    legalAddr: companyDocumentAddress(),
    bankAcc: c.bank_account || '',
    bankName: c.bank_name || '',
    bik: c.bik || '',
    corrAccount: c.corr_account || '',
    companyPhone: c.phone || '',
    cardNumber: c.card_number || '',
    cardHolder: c.card_holder || '',
    cardBank: c.card_bank || '',
    services: kpServices.map(s=>{
      const item = kpServiceItem(s);
      const rate = (s.customRate !== null && s.customRate !== undefined) ? s.customRate : item.rate;
      return {
        name: item.name,
        unit: item.unit,
        preliminaryArea: item.unit === 'м²' && s.preliminaryArea === true,
        rate: rate,
        listRate: item.rate,
        desc: item.desc || '',
        qty: Number(s.qty)||0,
        sum: rate * (Number(s.qty)||0),
      };
    }),
    discountType: document.getElementById('kp-discount-type').value,
    discountValue: parseFloat(document.getElementById('kp-discount-value').value) || 0,
    ...totals,
  };
}

const ROBOTO_REGULAR_B64 = "";
const ROBOTO_BOLD_B64 = "";

const ARHITTEK_LOGO_B64 = "data:image/png;base64,";

function companyDocumentAddress(){
  return String(state.companyInfo?.legal_address || '').trim();
}
function pdfCompanyAddress(doc, margin, y, reservedWidth=0){
  const address=companyDocumentAddress();if(!address)return;
  const width=doc.internal.pageSize.getWidth()-margin*2-reservedWidth;
  const lines=doc.splitTextToSize(address,width);
  const maxY=doc.internal.pageSize.getHeight()-5;
  if(reservedWidth){y=Math.min(y,maxY-(lines.length-1)*3.5);}
  else if(y+(lines.length-1)*3.5>maxY){doc.addPage();y=20;}
  doc.text(lines,margin,y);
}
function pdfRangeText(value){
  if(Array.isArray(value))return value.map(pdfRangeText);
  return typeof value==='string'?value.replace(/(\d)\s*[–—−]\s*(?=\d)/g,'$1-'):value;
}
function registerPdfFonts(doc){
  doc.addFileToVFS('Roboto-Regular.ttf', ROBOTO_REGULAR_B64);
  doc.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
  doc.addFileToVFS('Roboto-Bold.ttf', ROBOTO_BOLD_B64);
  doc.addFont('Roboto-Bold.ttf', 'Roboto', 'bold');
  doc.setFont('Roboto', 'normal');
  if(!doc._arhittekRanges){
    doc._arhittekRanges=true;
    const originalText=doc.text,originalSplit=doc.splitTextToSize;
    doc.text=function(text,...args){return originalText.call(this,pdfRangeText(text),...args);};
    doc.splitTextToSize=function(text,...args){return originalSplit.call(this,pdfRangeText(text),...args);};
  }
}

function pdfMoney(n){
  return fmt(n) + ' руб.';
}

function exportKpToPdf(){
  const data = getKpData();
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({unit:'mm', format:'a4'});
  registerPdfFonts(doc);

  const pageWidth = doc.internal.pageSize.getWidth();
  const margin = 15;

  // Logo badge
  const logoSize = 14;
  doc.addImage(ARHITTEK_LOGO_B64, 'PNG', margin, 10, logoSize, logoSize * (87/100));

  const textX = margin + logoSize + 4;
  doc.setFont('Roboto','bold');
  doc.setFontSize(18);
  doc.setTextColor(0);
  doc.text('ARHIT', textX, 19);
  const arhitWidth = doc.getTextWidth('ARHIT');
  doc.setTextColor(69,134,236);
  doc.text('TEK', textX + arhitWidth, 19);
  doc.setTextColor(0);
  doc.setFontSize(11);
  doc.setFont('Roboto','normal');
  doc.text('Коммерческое предложение', textX, 26);
  doc.setFontSize(9);
  doc.setTextColor(120);
  doc.text(`Дата: ${fmtDate(data.date)}`, pageWidth - margin, 20, {align:'right'});
  doc.setTextColor(0);

  let y = 38;
  doc.setFontSize(10);
  const infoRows = [
    ['Клиент:', data.clientName || 'Клиент'],
    data.clientPhone && ['Телефон:', data.clientPhone],
    data.object && ['Объект:', data.object],
    data.deadline && ['Срок:', data.deadline],
    data.startDate && ['Начало работ:', data.startDate],
  ].filter(Boolean);

  infoRows.forEach(([lbl, val])=>{
    doc.setFont('Roboto','bold'); doc.text(lbl, margin, y);
    doc.setFont('Roboto','normal'); doc.text(val, margin + 32, y);
    y += 6;
  });

  y += 4;

  const rows = data.services.map((s,i)=>[
    String(i+1),
    s.name,
    `${s.qty} ${s.unit}${s.preliminaryArea?' (предв.)':''}`,
    s.rate !== s.listRate ? `${pdfMoney(s.rate)}*` : `${pdfMoney(s.rate)}`,
    `${pdfMoney(s.sum)}${s.preliminaryArea?' (предв.)':''}`,
  ]);
  const preliminary = data.services.some(s=>s.preliminaryArea);
  const hasCustomRates = data.services.some(s=>s.rate !== s.listRate);

  doc.autoTable({
    startY: y,
    head: [['№', 'Услуга', 'Объём', 'Ставка', 'Сумма']],
    body: rows,
    theme: 'grid',
    headStyles: {fillColor: [69,134,236], textColor: [255,255,255], fontStyle:'bold', font:'Roboto'},
    styles: {fontSize: 9, cellPadding: 3, font:'Roboto'},
    columnStyles: {0:{cellWidth:10}, 2:{cellWidth:25}, 3:{cellWidth:30}, 4:{cellWidth:30}},
    margin: {left: margin, right: margin},
  });

  let finalY = doc.lastAutoTable.finalY + 5;

  if(hasCustomRates){
    doc.setFontSize(8);
    doc.setTextColor(140);
    doc.text('* индивидуальная договорная цена', margin, finalY);
    doc.setTextColor(0);
    finalY += 6;
  }

  if(preliminary){
    doc.setFont('Roboto','normal');doc.setFontSize(9);doc.setTextColor(70);
    const note = 'Предварительная площадь: отмеченные позиции могут увеличиться или уменьшиться в ходе проектирования. Итоговая стоимость рассчитывается по уточнённой площади по согласованному тарифу за м² и изменяется пропорционально — как в большую, так и в меньшую сторону.';
    const lines = doc.splitTextToSize(note,pageWidth-margin*2);
    if(finalY+lines.length*4.5+6>270){doc.addPage();finalY=20;}
    doc.text(lines,margin,finalY);finalY+=lines.length*4.5+6;doc.setTextColor(0);
  }

  // Состав услуг (описания тарифов)
  const withDesc = data.services.filter(s=>s.desc);
  if(withDesc.length){
    doc.setFont('Roboto','bold');
    doc.setFontSize(9);
    doc.text('Что входит в услуги:', margin, finalY);
    finalY += 5;
    doc.setFont('Roboto','normal');
    doc.setFontSize(8);
    doc.setTextColor(90);
    withDesc.forEach(s=>{
      const lines = doc.splitTextToSize(`${s.name}: ${s.desc}`, pageWidth - margin*2);
      lines.forEach(line=>{
        if(finalY > 270){ doc.addPage(); finalY = 20; }
        doc.text(line, margin, finalY);
        finalY += 4.2;
      });
      finalY += 1.5;
    });
    doc.setTextColor(0);
    finalY += 3;
  }

  if(finalY > 250){ doc.addPage(); finalY = 20; }

  const labelX = pageWidth - margin - 45;
  const valueX = pageWidth - margin;

  doc.setFontSize(10);
  doc.setFont('Roboto','normal');
  doc.text('Сумма услуг:', labelX, finalY, {align:'right'});
  doc.text(pdfMoney(data.subtotal), valueX, finalY, {align:'right'});
  finalY += 6;

  if(data.discountAmount > 0){
    doc.text('Скидка:', labelX, finalY, {align:'right'});
    doc.text(`- ${pdfMoney(data.discountAmount)}`, valueX, finalY, {align:'right'});
    finalY += 6;
  }

  doc.setFont('Roboto','bold');
  doc.setFontSize(12);
  doc.text(preliminary?'Предварительный итог:':'Итого к оплате:', labelX, finalY, {align:'right'});
  doc.text(pdfMoney(data.total), valueX, finalY, {align:'right'});
  finalY += 8;

  doc.setFont('Roboto','normal');
  doc.setFontSize(10);
  doc.text('Аванс (50%):', labelX, finalY, {align:'right'});
  doc.text(pdfMoney(data.advance), valueX, finalY, {align:'right'});
  finalY += 6;
  doc.text('Остаток после аванса:', labelX, finalY, {align:'right'});
  doc.text(pdfMoney(data.remainder), valueX, finalY, {align:'right'});

  finalY += 14;

  // Requisites block
  const showAnyReq = data.showCompany || data.showAccount || data.showCard;
  if(showAnyReq){
    if(finalY > 250){ doc.addPage(); finalY = 20; }
    doc.setDrawColor(180); doc.line(margin, finalY, pageWidth-margin, finalY); finalY += 6;
    doc.setFont('Roboto','bold'); doc.setFontSize(9); doc.setTextColor(0);
    const reqTitle = ['Реквизиты исполнителя'];
    const methods = [];
    if(data.showAccount) methods.push('расчётный счёт');
    if(data.showCard) methods.push('банковская карта');
    if(methods.length) reqTitle.push(`(оплата: ${methods.join(', ')})`);
    doc.text(reqTitle.join(' '), margin, finalY); finalY += 5;
    doc.setFont('Roboto','normal'); doc.setFontSize(8); doc.setTextColor(50);

    let reqRows = [];

    if(data.showCompany){
      if(data.company) reqRows.push(`Компания: ${data.company}`);
      if(data.inn) reqRows.push(`ИНН: ${data.inn}${data.kpp?' | КПП: '+data.kpp:''}${data.ogrn?' | ОГРН: '+data.ogrn:''}`);
      if(data.legalAddr) reqRows.push(`Адрес: ${data.legalAddr}`);
      if(data.companyPhone) reqRows.push(`Тел.: ${data.companyPhone}`);
    }

    if(data.showAccount){
      if(!data.bankAcc) reqRows.push('⚠ Реквизиты счёта не заполнены — заполните в разделе «Компания»');
      if(data.bankAcc) reqRows.push(`Р/с: ${data.bankAcc}`);
      if(data.bankName) reqRows.push(`Банк: ${data.bankName}`);
      if(data.bik) reqRows.push(`БИК: ${data.bik}${data.corrAccount?' | К/с: '+data.corrAccount:''}`);
    }

    if(data.showCard){
      if(!data.cardNumber && !data.cardHolder) reqRows.push('⚠ Реквизиты карты не заполнены — заполните в разделе «Компания»');
      if(data.cardNumber) reqRows.push(`Карта для оплаты: ${data.cardNumber}`);
      if(data.cardHolder) reqRows.push(`Получатель: ${data.cardHolder}`);
      if(data.cardBank) reqRows.push(`Банк карты: ${data.cardBank}`);
    }

    reqRows.forEach(r=>{ doc.text(r, margin, finalY); finalY += 4.5; });
    finalY += 4;
    doc.setTextColor(140);
  }else{
    doc.setFont('Roboto','normal'); doc.setFontSize(8); doc.setTextColor(140);
  }

  if(finalY > 272) finalY = 272;
  doc.text('ARHITTEK — архитектурное проектирование, дизайн интерьера, ремонт под ключ', margin, finalY);
  pdfCompanyAddress(doc, margin, finalY+5, 0);

  const fileName = kpFileName(data, 'pdf');
  doc.save(fileName);
  showToast('PDF скачивается...');
}

function exportKpToXlsx(){
  const data = getKpData();
  const wb = XLSX.utils.book_new();

  const rows = [];
  rows.push(['ARHITTEK — Коммерческое предложение']);
  rows.push([]);
  rows.push(['Клиент', data.clientName]);
  if(data.clientPhone) rows.push(['Телефон', data.clientPhone]);
  if(data.object) rows.push(['Объект', data.object]);
  rows.push(['Дата', fmtDate(data.date)]);
  rows.push([]);
  rows.push(['№','Услуга','Объём','Ед.','Цена по прайсу, ₽','Договорная цена, ₽','Сумма, ₽']);
  data.services.forEach((s,i)=>{
    rows.push([i+1, s.name, s.qty, s.unit, s.listRate, s.rate, s.sum]);
  });
  rows.push([]);
  rows.push(['', '', '', '', '', 'Сумма услуг:', data.subtotal]);
  if(data.discountAmount > 0) rows.push(['', '', '', '', '', 'Скидка:', -data.discountAmount]);
  rows.push(['', '', '', '', '', 'Итого:', data.total]);
  rows.push(['', '', '', '', '', 'Аванс (50%):', data.advance]);
  rows.push(['', '', '', '', '', 'Остаток после аванса:', data.remainder]);

  const withDesc = data.services.filter(s=>s.desc);
  if(withDesc.length){
    rows.push([]);
    rows.push(['Что входит в услуги:']);
    withDesc.forEach(s=>{
      rows.push([s.name]);
      rows.push(['', s.desc]);
    });
  }

  if(data.deadline || data.startDate){
    rows.push([]);
    rows.push(['Сроки:']);
    if(data.startDate) rows.push(['Начало работ', data.startDate]);
    if(data.deadline) rows.push(['Срок выполнения', data.deadline]);
  }

  // Requisites — выбранные блоки
  if(data.showCompany || data.showAccount || data.showCard){
    rows.push([]);
    const xlsMethods = [];
    if(data.showAccount) xlsMethods.push('расчётный счёт');
    if(data.showCard) xlsMethods.push('банковская карта');
    rows.push([`Реквизиты исполнителя${xlsMethods.length?' (оплата: '+xlsMethods.join(', ')+')':''}`]);
    if(data.showCompany){
      if(data.company) rows.push(['Компания', data.company]);
      if(data.inn) rows.push(['ИНН / КПП / ОГРН', [data.inn, data.kpp, data.ogrn].filter(Boolean).join(' / ')]);
      if(data.legalAddr) rows.push(['Юридический адрес', data.legalAddr]);
      if(data.companyPhone) rows.push(['Телефон', data.companyPhone]);
    }
    if(data.showAccount){
      if(data.bankAcc) rows.push(['Р/с', data.bankAcc]);
      if(data.bankName) rows.push(['Банк', data.bankName]);
      if(data.bik) rows.push(['БИК / К/с', [data.bik, data.corrAccount].filter(Boolean).join(' / ')]);
    }
    if(data.showCard){
      if(data.cardNumber) rows.push(['Карта для оплаты', data.cardNumber]);
      if(data.cardHolder) rows.push(['Получатель', data.cardHolder]);
      if(data.cardBank) rows.push(['Банк карты', data.cardBank]);
    }
  }

  const ws = XLSX.utils.aoa_to_sheet(rows);
  XLSX.utils.book_append_sheet(wb, ws, 'КП');

  const fileName = kpFileName(data, 'xlsx');
  XLSX.writeFile(wb, fileName);
  showToast('Excel скачивается...');
}

function openKpView(){
  if(!canUseDocuments())return;
  if(!kpServices.length) addKpService();
  if(!document.getElementById('kp-date').value) document.getElementById('kp-date').value = financeToday();
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  document.getElementById('view-kp').classList.add('active');
  renderKpSavedList();
  window.scrollTo(0,0);
}

let editingKpId = null;
let editingKpProjectId = null;
let kpSaveInFlight = false;

function resetKpForm(){
  editingKpId = null;
  editingKpProjectId = null;
  kpServices = [];
  document.getElementById('kp-client-name').value = '';
  document.getElementById('kp-client-phone').value = '';
  document.getElementById('kp-object').value = '';
  document.getElementById('kp-date').value = financeToday();
  document.getElementById('kp-deadline').value = '';
  document.getElementById('kp-start').value = '';
  document.getElementById('kp-discount-type').value = 'percent';
  document.getElementById('kp-discount-value').value = '';
  kpPaymentMethod = 'account';
  document.querySelectorAll('#kp-payment-method .yn-btn').forEach(b=>b.classList.toggle('selected', b.dataset.value==='account'));
  addKpService();
}

function loadKpForm(kp){
  editingKpId = kp.id;
  editingKpProjectId = kp.project_id || null;
  document.getElementById('kp-client-name').value = kp.client_name || '';
  document.getElementById('kp-client-phone').value = kp.client_phone || '';
  document.getElementById('kp-object').value = kp.object || '';
  document.getElementById('kp-date').value = kp.kp_date || financeToday();
  document.getElementById('kp-deadline').value = kp.deadline || '';
  document.getElementById('kp-start').value = kp.start_date || '';
  document.getElementById('kp-discount-type').value = kp.discount_type || 'percent';
  document.getElementById('kp-discount-value').value = kp.discount_value || '';

  kpPaymentMethod = kp.payment_method || 'account';
  document.querySelectorAll('#kp-payment-method .yn-btn').forEach(b=>b.classList.toggle('selected', b.dataset.value===kpPaymentMethod));

  kpServices = (kp.services || []).map(s=>({
    id: 'kpsvc-' + (++kpServiceCounter),
    catalogIndex: s.catalogIndex || 0,
    qty: s.qty ?? 1,
    snapshot: kpServiceSnapshot(kpServiceItem(s)),
    customRate: (s.customRate===undefined ? null : s.customRate),
    preliminaryArea: s.preliminaryArea === true,
  }));
  if(!kpServices.length) addKpService();
  renderKpServices();
}

async function saveKpForm(){
  if(kpSaveInFlight) return false;
  if(kpServices.some(s=>!Number.isFinite(Number(s.qty)) || Number(s.qty)<0 || !Number.isFinite(Number(s.customRate ?? kpServiceItem(s).rate)) || Number(s.customRate ?? kpServiceItem(s).rate)<0)){
    showToast('Количество и цена услуги должны быть неотрицательными');return false;
  }
  const data = getKpData();
  const payload = {
    project_id: editingProjectId || editingKpProjectId || null,
    client_name: document.getElementById('kp-client-name').value.trim(),
    client_phone: document.getElementById('kp-client-phone').value.trim(),
    object: document.getElementById('kp-object').value.trim(),
    kp_date: document.getElementById('kp-date').value || financeToday(),
    deadline: document.getElementById('kp-deadline').value.trim(),
    start_date: document.getElementById('kp-start').value.trim(),
    payment_method: kpPaymentMethod,
    discount_type: document.getElementById('kp-discount-type').value,
    discount_value: parseFloat(document.getElementById('kp-discount-value').value) || 0,
    services: kpServices.map(s=>({catalogIndex: s.catalogIndex, snapshot:kpServiceSnapshot(kpServiceItem(s)), qty: s.qty, customRate: s.customRate, preliminaryArea: s.preliminaryArea === true})),
    updated_at: new Date().toISOString(),
  };

  kpSaveInFlight=true;
  const saveButton=document.getElementById('kpSaveBtn');if(saveButton)saveButton.disabled=true;
  showToast('Сохранение…');
  try{
    if(editingKpId){
      const {error} = await sb.from('kp_forms').update(payload).eq('id', editingKpId);
      if(error) throw error;
    }else{
      const {data: inserted, error} = await sb.from('kp_forms').insert(payload).select().single();
      if(error) throw error;
      editingKpId = inserted.id;
    }
    showToast('КП сохранено');
    await loadAll();
    renderKpSavedList();
    if(editingProjectId) renderKpListForProject(editingProjectId);
    document.getElementById('view-kp').dataset.dirty='0';
    return true;
  }catch(e){
    console.error(e);
    showToast('Ошибка сохранения КП');
    return false;
  }finally{kpSaveInFlight=false;if(saveButton)saveButton.disabled=false;}
}

async function deleteKpForm(id){
  if(!confirm('Удалить это КП? Действие необратимо.')) return;
  showToast('Удаление…');
  try{
    const {error} = await sb.from('kp_forms').delete().eq('id', id);
    if(error) throw error;
    if(editingKpId === id) resetKpForm();
    showToast('КП удалено');
    await loadAll();
    renderKpSavedList();
    if(editingProjectId) renderKpListForProject(editingProjectId);
  }catch(e){
    console.error(e);
    showToast('Ошибка удаления');
  }
}

function kpRowSummary(kp){
  const flat = kpFlatCatalog();
  const services = kp.services || [];
  let subtotal = 0;
  services.forEach(s=>{
    const item = kpServiceItem(s);
    const rate = (s.customRate!==null && s.customRate!==undefined) ? s.customRate : item.rate;
    subtotal += rate * (Number(s.qty)||0);
  });
  let discountAmount = 0;
  if(kp.discount_type === 'percent') discountAmount = subtotal * (Number(kp.discount_value)||0) / 100;
  else discountAmount = Number(kp.discount_value)||0;
  return Math.max(0, subtotal - discountAmount);
}

function loadKpFormById(id){
  const kp = state.kpForms.find(k=>k.id===id);
  if(!kp) return;
  const sheetOpen = document.getElementById('projectSheetOverlay').classList.contains('active');
  if(sheetOpen) closeProjectSheet();
  loadKpForm(kp);
  openKpView();
}

function renderKpSavedList(){
  const container = document.getElementById('kpSavedList');
  if(!state.kpForms.length){
    container.innerHTML = '<div class="empty-state">Сохранённых КП пока нет</div>';
    return;
  }
  container.innerHTML = state.kpForms.map(kp=>{
    const total = kpRowSummary(kp);
    const proj = kp.project_id ? state.projects.find(p=>p.id===kp.project_id) : null;
    return `<div class="list-item">
      <div style="cursor:pointer; flex:1;" onclick="loadKpFormById('${kp.id}')">
        <div class="li-name">${escapeHtml(kp.client_name || 'Без имени')}</div>
        <div class="li-meta">${escapeHtml(kp.object||'')}${proj?' · '+escapeHtml(proj.name):''} · ${fmtDate(kp.kp_date)} · ${fmtMoney(total)}</div>
      </div>
      <div class="li-actions">
        <button class="icon-btn" title="Редактировать" onclick="loadKpFormById('${kp.id}')">✏️</button>
        <button class="icon-btn danger" title="Удалить" onclick="deleteKpForm('${kp.id}')">🗑</button>
      </div>
    </div>`;
  }).join('');
}

function openKpViewForProject(projectId){
  const p = state.projects.find(x=>x.id===projectId);
  if(!p) return;
  closeProjectSheet();

  resetKpForm();
  editingKpProjectId = projectId;

  openKpView();
  document.getElementById('kp-client-name').value = p.client_name || '';
  document.getElementById('kp-client-phone').value = p.phone || '';
  document.getElementById('kp-object').value = p.address || p.name || '';
}

document.getElementById('kpNewBtn').addEventListener('click', resetKpForm);
document.getElementById('kpSaveBtn').addEventListener('click', saveKpForm);

document.getElementById('pf-create-kp').addEventListener('click', ()=>{
  if(editingProjectId) openKpViewForProject(editingProjectId);
});

document.getElementById('objBack').addEventListener('click', ()=>{
  currentObjectId = null;
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
  document.getElementById('view-construction').classList.add('active');
  document.querySelector('.nav-btn[data-view="view-construction"]').classList.add('active');
  const fab = document.getElementById('addProjectFab');
  if(fab){ fab.style.display = ''; fab.title = 'Добавить объект'; }
  const y=constructionReturnScrollY||0;
  requestAnimationFrame(()=>window.scrollTo(0,y));
});

let navigationRenderVersion=0;
document.querySelectorAll('.nav-btn').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    const navigationVersion=++navigationRenderVersion;
    document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
    document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById(btn.dataset.view).classList.add('active');
    window.scrollTo({top:0, behavior:'smooth'});
    // Показываем FAB только в Проектный и Стройка
    const fab = document.getElementById('addProjectFab');
    const showFab = ['view-projects','view-construction'].includes(btn.dataset.view);
    if(fab){
      fab.style.display = showFab ? '' : 'none';
      fab.title = btn.dataset.view === 'view-construction' ? 'Добавить объект' : 'Добавить проект';
    }
    // В Готовые проекты — загружаем карточки
    if(btn.dataset.view === 'view-cards') loadCards();
    // В Финансы — рендерим зарплаты и P&L (раньше это делал отдельный openFinanceBtn)
    if(btn.dataset.view === 'view-finance'){
      // Paint the selected page before synchronous financial calculations.
      requestAnimationFrame(()=>setTimeout(()=>{
        if(navigationVersion!==navigationRenderVersion||!document.getElementById('view-finance').classList.contains('active'))return;
        renderFinanceSalaries();renderAnalytics();
      },0));
    }
  });
});

